"Зілля отрути":"Зелье яда",
"Виглядає як зілля лікування. Хто вип’є — 3к6 шкоди отрутою та рятівний Статури СК 13 або отруєний.":"Выглядит как зелье лечения. Кто выпьет — 3к6 урона ядом и спасбросок Телосложения Сл 13 или отравлен.",
