"Полум’яний язик":"Язык пламени",
"Бонусною дією вимов команду — клинок спалахує: +2к6 шкоди вогнем, світло 40 фт.":"Бонусным действием произнеси команду — клинок вспыхивает: +2к6 урона огнём, свет 40 фт.",
"+2к6 вогнем":"+2к6 огнём",
"Вбивця драконів":"Убийца драконов",
"Меч +1. Проти драконів +3к6 шкоди.":"Меч +1. Против драконов +3к6 урона.",
"+3к6 проти драконів":"+3к6 против драконов",
"Сокира або меч +1. Проти велетнів +2к6 шкоди, ціль — рятівний Сили СК 15 або падає.":"Топор или меч +1. Против великанов +2к6 урона, цель — спасбросок Силы Сл 15 или падает.",
"Сонячний клинок":"Солнечный клинок",
"Руків’я, що створює клинок світла: довгий меч +2 з фехтувальною властивістю, промениста шкода, +1к8 проти нежиті.":"Рукоять, создающая клинок света: длинный меч +2 со свойством «фехтовальное», урон излучением, +1к8 против нежити.",
"Фехтувальна, універсальна (1к10)":"Фехтовальное, универсальное (1к10)",
"Меч крадіжки життя":"Меч кражи жизни",
"При критичному влучанні по живій істоті: +3к6 некротичної шкоди і ти отримуєш стільки ж тимчасових ХП.":"При критическом попадании по живому существу: +3к6 некротического урона и ты получаешь столько же временных ХП.",
"Меч поранення":"Меч ранения",
"Рани не лікуються звичайно; раз на хід ціль отримує додатково 1к4 некротичної шкоди за кожне поранення.":"Раны не лечатся обычным образом; раз в ход цель получает дополнительно 1к4 некротического урона за каждое ранение.",
"Булава руйнування":"Булава разрушения",
"Проти виродків і нежиті +2к6 променистої шкоди; при 25 ХП і менше — рятівний Мудрості СК 15 або знищення.":"Против исчадий и нежити +2к6 урона излучением; при 25 ХП и меньше — спасбросок Мудрости Сл 15 или уничтожение.",
"Булава розгрому":"Булава кары",
"Булава +1. При 20 на кидку атаки +2к6 шкоди (по конструктах +4к6).":"Булава +1. При 20 на броске атаки +2к6 урона (по конструктам +4к6).",
"Булава жаху":"Булава ужаса",
"3 заряди: наведи жах на всіх у радіусі 30 фт (рятівний Мудрості СК 15).":"3 заряда: наведи ужас на всех в радиусе 30 фт (спасбросок Мудрости Сл 15).",
"Кинджал отрути":"Кинжал яда",
