"Сокира берсерка":"Топор берсерка",
"Сокира +1, +1 ХП за кожен рівень. Прокляття: важко розлучитися зі зброєю, лють у бою.":"Топор +1, +1 ХП за каждый уровень. Проклятие: трудно расстаться с оружием, ярость в бою.",
"Жорстока зброя":"Жестокое оружие",
"При 20 на кидку атаки ціль отримує ще 7 шкоди.":"При 20 на броске атаки цель получает ещё 7 урона.",
"Стріла вбивства":"Стрела убийства",
"Зачарована проти одного виду істот: ціль робить рятівний Статури СК 17 або отримує ще 6к10 колючої шкоди.":"Зачарована против одного вида существ: цель совершает спасбросок Телосложения Сл 17 или получает ещё 6к10 колющего урона.",
"Морозний клинок":"Морозный клинок",
