"+1к6 холодом":"+1к6 холодом",
"Танцюючий меч":"Танцующий меч",
"Бонусною дією підкинь меч — він ширяє та атакує сам (до 4 разів) у межах 30 фт.":"Бонусным действием подбрось меч — он парит и атакует сам (до 4 раз) в пределах 30 фт.",
"Меч гостроти":"Меч остроты",
"Максимальна шкода по предметах. При 20 на атаці +14 рубальної шкоди і ще 1к20 — шанс відрубати кінцівку.":"Максимальный урон по предметам. При 20 на атаке +14 рубящего урона и ещё 1к20 — шанс отрубить конечность.",
"Викрадач дев’яти життів":"Похититель девяти жизней",
