"Ятаган швидкості":"Скимитар скорости",
"Ятаган +2. Бонусною дією можеш зробити ще одну атаку ним.":"Скимитар +2. Бонусным действием можешь совершить ещё одну атаку им.",
"Дварфійський метальний молот":"Дварфийский метательный молот",
"так (дварф)":"да (дварф)",
"Бойовий молот +3, метальна (20/60), повертається в руку. Кинутий — +1к8 шкоди (+2к8 по велетнях).":"Боевой молот +3, метательный (20/60), возвращается в руку. Брошенный — +1к8 урона (+2к8 по великанам).",
"Лук клятви":"Лук клятвы",
