"Каблучка стрибків":"Кольцо прыжков",
"Бонусною дією накладай на себе «Стрибок» за бажанням.":"Бонусным действием накладывай на себя «Прыжок» по желанию.",
"Каблучка захисту розуму":"Кольцо защиты разума",
"Імунітет до читання думок і визначення брехні.":"Иммунитет к чтению мыслей и определению лжи.",
"Каблучка плавання":"Кольцо плавания",
"Швидкість плавання 40 фт.":"Скорость плавания 40 фт.",
"Каблучка тепла":"Кольцо тепла",
"Опір холоду; комфорт у морозі до −50°.":"Сопротивление холоду; комфорт в мороз до −50°.",
"Каблучка ходіння по воді":"Кольцо хождения по воде",
"Можеш стояти й ходити по рідині.":"Можешь стоять и ходить по жидкости.",
"Каблучка захисту":"Кольцо защиты",
"+1 до КЗ і рятівних кидків.":"+1 к КД и спасброскам.",
"Каблучка влади над тваринами":"Кольцо власти над животными",
