"Каблучка ухилення":"Кольцо уклонения",
"3 заряди: реакцією перетвори провалений рятівний Спритності на успішний.":"3 заряда: реакцией превращай проваленный спасбросок Ловкости в успешный.",
"Каблучка падіння пір’їнкою":"Кольцо падения пёрышком",
"Падаєш повільно (60 фт за раунд) і не отримуєш шкоди від падіння.":"Падаешь медленно (60 фт за раунд) и не получаешь урона от падения.",
"Каблучка свободи дій":"Кольцо свободы действий",
"Складна місцевість не сповільнює, магія не паралізує й не сповільнює тебе.":"Труднопроходимая местность не замедляет, магия не парализует и не замедляет тебя.",
"Каблучка опору":"Кольцо сопротивления",
"Опір одному типу шкоди залежно від каменю.":"Сопротивление одному виду урона в зависимости от камня.",
"Каблучка зберігання заклять":"Кольцо хранения заклинаний",
