"Каблучка тарана":"Кольцо тарана",
"3 заряди: силовий удар-таран 2к10 силової шкоди за заряд, відкидає ціль.":"3 заряда: силовой удар-таран 2к10 урона силовым полем за заряд, отбрасывает цель.",
"Каблучка наскрізного зору":"Кольцо рентгеновского зрения",
