"Каблучка регенерації":"Кольцо регенерации",
"Кожні 10 хвилин відновлюєш 1к6 ХП; відрощуєш втрачені кінцівки.":"Каждые 10 минут восстанавливаешь 1к6 ХП; отращиваешь утраченные конечности.",
"Каблучка падучих зірок":"Кольцо падающих звёзд",
"Вночі під відкритим небом: «Танцюючі вогники», «Світло», кульові блискавки та падучі зірки.":"Ночью под открытым небом: «Пляшущие огоньки», «Свет», шаровые молнии и падающие звёзды.",
"Каблучка телекінезу":"Кольцо телекинеза",
"Твориш «Телекінез» за бажанням.":"Накладываешь «Телекинез» по желанию.",
"Каблучка невидимості":"Кольцо невидимости",
"Дією стаєш невидимим, доки не атакуєш, не створиш закляття або не знімеш ефект.":"Действием становишься невидимым, пока не атакуешь, не наложишь заклинание или не снимешь эффект.",
"Каблучка відбиття заклять":"Кольцо отражения заклинаний",
"Перевага на рятівні від заклять; при успіху закляття може відбитися на заклинача.":"Преимущество на спасброски от заклинаний; при успехе заклинание может отразиться на заклинателя.",
"Каблучка трьох бажань":"Кольцо трёх желаний",
"3 заряди закляття «Бажання».":"3 заряда заклинания «Исполнение желаний».",
"Паличка магічних стріл":"Волшебная палочка волшебных стрел",
"7 зарядів: «Магічна стріла» (1 заряд за коло). Відновлює 1к6+1 на світанку.":"7 зарядов: «Волшебная стрела» (1 заряд за уровень). Восстанавливает 1к6+1 на рассвете.",
