"Жезл правління":"Жезл правления",
"Раз на день: істоти в межах 120 фт роблять рятівний Мудрості СК 15 або зачаровані тобою на 8 годин.":"Раз в день: существа в пределах 120 фт совершают спасбросок Мудрости Сл 15 или очарованы тобой на 8 часов.",
"Жезл поглинання":"Жезл поглощения",
"Реакцією поглинай закляття, спрямоване тільки на тебе; накопичену енергію використовуй для своїх заклять.":"Реакцией поглощай заклинание, направленное только на тебя; накопленную энергию используй для своих заклинаний.",
"Жезл пильності":"Жезл бдительности",
