"Сумка зберігання":"Сумка хранения",
"Всередині значно більша: до 500 фнт / 64 куб. фт. Важить завжди 15 фнт.":"Внутри намного больше: до 500 фнт / 64 куб. фт. Всегда весит 15 фнт.",
"Мішечок фокусів":"Сумка фокусов",
