"Чоботи ельфів":"Сапоги эльфов",
"Кроки беззвучні, перевага на Непомітність, що спирається на тихе пересування.":"Шаги беззвучны, преимущество на Скрытность, основанную на тихом передвижении.",
"Чоботи кроків і стрибків":"Сапоги ходьбы и прыжков",
"Швидкість ходьби мінімум 30 фт, стрибки втричі далі.":"Скорость ходьбы минимум 30 фт, прыжки втрое дальше.",
"Чоботи зимових земель":"Сапоги зимних земель",
