"Крилаті чоботи":"Крылатые сапоги",
"До 4 годин на день літаєш зі швидкістю ходьби.":"До 4 часов в день летаешь со скоростью ходьбы.",
"Наручі стрільця":"Наручи стрельбы из лука",
