"Плащ захисту":"Плащ защиты",
"Плащ морського ската":"Плащ ската",
"Дихаєш під водою, швидкість плавання 60 фт.":"Дышишь под водой, скорость плавания 60 фт.",
"Глечик нескінченної води":"Графин бесконечной воды",
"Створює прісну або солону воду — від струмка до потужного гейзера.":"Создаёт пресную или солёную воду — от ручейка до мощного гейзера.",
"Колода ілюзій":"Колода иллюзий",
