"Капелюх маскування":"Шляпа маскировки",
"Твориш «Маскування» за бажанням.":"Накладываешь «Маскировку» по желанию.",
"Пов’язка інтелекту":"Повязка интеллекта",
"Твій Інтелект стає 19 (якщо він не вищий).":"Твой Интеллект становится 19 (если он не выше).",
