"Намисто адаптації":"Ожерелье адаптации",
"Дихаєш у будь-якому середовищі, перевага на рятівні від газів.":"Дышишь в любой среде, преимущество на спасброски от газов.",
"Перлина сили":"Жемчужина силы",
