"Періапт здоров’я":"Периапт здоровья",
"Періапт загоєння ран":"Периапт заживления ран",
"Стабілізуєшся автоматично при 0 ХП; відновлення ХП кістками хітів подвоюється.":"Стабилизируешься автоматически при 0 ХП; восстановление ХП костями хитов удваивается.",
"Мантія корисних речей":"Мантия полезных вещей",
