"Амулет здоров’я":"Амулет здоровья",
"Твоя Статура стає 19 (якщо вона не вища).":"Твоё Телосложение становится 19 (если оно не выше).",
"Пояс дварфів":"Пояс дварфов",
"+2 до Статури (макс. 20), темний зір, опір отруті, мова дварфів.":"+2 к Телосложению (макс. 20), тёмное зрение, сопротивление яду, дварфийский язык.",
"Пояс сили пагорбового велетня":"Пояс силы холмового великана",
"Твоя Сила стає 21.":"Твоя Сила становится 21.",
"Чоботи левітації":"Сапоги левитации",
"Твориш «Левітацію» на себе за бажанням.":"Накладываешь «Левитацию» на себя по желанию.",
"Чоботи швидкості":"Сапоги скорости",
"Бонусною дією подвоюєш швидкість ходьби на 10 хвилин на день.":"Бонусным действием удваиваешь скорость ходьбы на 10 минут в день.",
"Наручі захисту":"Наручи защиты",
"+2 до КЗ, якщо не носиш обладунку й щита.":"+2 к КД, если не носишь доспех и щит.",
"Плащ зміщення":"Плащ смещения",
"Твій образ зміщений: атаки по тобі з перешкодою, доки тебе не поранять.":"Твой образ смещён: атаки по тебе с помехой, пока тебя не ранят.",
"Плащ кажана":"Плащ летучей мыши",
