"Мантія опору закляттям":"Мантия сопротивления заклинаниям",
"Перевага на рятівні кидки від заклять.":"Преимущество на спасброски от заклинаний.",
"Пір’їнка Кваала":"Перо Кваала",
"Одноразова пір’їнка, що стає якорем, птахом, віялом, човном, деревом або батогом.":"Одноразовое перо, которое становится якорем, птицей, веером, лодкой, деревом или кнутом.",
"Фігурка дивовижної сили":"Статуэтка чудесной силы",
"Статуетка, що оживає й стає звіром на твоєму боці (вид визначає майстер).":"Статуэтка, которая оживает и становится зверем на твоей стороне (вид определяет мастер).",
"Складаний човен":"Складная лодка",
"Скринька, що розкладається у човен або корабель.":"Шкатулка, раскладывающаяся в лодку или корабль.",
"Зручний ранець":"Удобный рюкзак",
